     8→import {
     9→  Button,
    10→  GoBackHeader,
    11→  Loading,
    12→  RadioButton,
    13→  ScreenLayout,
    14→} from "shared/components";
    15→import { Colors, TextSize } from "shared/styles";
    16→import { DisableKeyStorageModal } from "./fragments";
    17→
    18→export const Encryption: React.FC<
    19→  NativeStackScreenProps<Routes, "encryption">
    20→> = ({ navigation }) => {
    21→  const [backupState, setBackupState] = useState<MappedBackupState>("unknown");
    22→  const [recoveryState, setRecoveryState] = useState<RecoveryState>(
    23→    RecoveryState.Unknown,
    24→  );
    25→  const [isLoading, setIsLoading] = useState<boolean>(true);
    26→  const [isDisableKeyStorageModalVisible, setIsDisableKeyStorageModalVisible] =
    27→    useState<boolean>(false);
    28→  const isBackupEnabled = backupState === "enabled";
    29→  const isTransitioning =
    30→    backupState === "enabling" || backupState === "disabling";
    31→
    32→  const recoveryText = () => {
    33→    if (recoveryState === RecoveryState.Enabled) return "Change recovery key";
    34→    if (recoveryState === RecoveryState.Disabled) {
    35→      return "Set up a recovery key";
    36→    }
    37→    if (recoveryState === RecoveryState.Incomplete) {
    38→      return "Enter existing recovery key and validate your device.";
    39→    }
    40→    return "Set up a recovery key";
    41→  };
    42→
    43→  useEffect(() => {
    44→    const listener = EncryptionService.subscribeToBackupState((state) => {
    45→      setBackupState(state);
    46→      setIsLoading(false);
    47→    });
    48→
    49→    return () => {
    50→      listener.cancel();
    51→    };
    52→  }, []);
    53→
    54→  useEffect(() => {
    55→    const listener = EncryptionService.subscribeToRecoveryState((state) => {
    56→      setRecoveryState(state);
    57→      setIsLoading(false);
    58→    });
    59→
    60→    return () => {
    61→      listener.cancel();
    62→    };
    63→  }, []);
    64→
    65→  const handleToggleKeyStorage = async () => {
    66→    try {
    67→      if (isBackupEnabled) {
    68→        setIsDisableKeyStorageModalVisible(true);
    69→        return;
    70→      }
    71→
    72→      // Enable backups when state is unknown (backup not enabled)
    73→      setIsLoading(true);
    74→      await EncryptionService.enableBackups();
    75→      setIsLoading(false);
    76→    } catch (error) {
    77→      console.error("Failed to toggle key storage:", error);
    78→      Toast.show({
    79→        text1: "Failed to toggle key storage",
    80→        text2: error instanceof Error ? error.message : "Unknown error",
    81→        type: "error",
    82→      });
    83→    }
    84→  };
    85→
    86→  return (
    87→    <ScreenLayout>
    88→      <Block flex={1} align="center" gap={40}>
    89→        <GoBackHeader title="Encryption" margins={0} />
    90→        {recoveryState !== RecoveryState.Incomplete && (
    91→          <Block gap={8} width="100%">
    92→            <Text
    93→              size={TextSize.tiny}
    94→              color={Colors.white50}
    95→              paddings={[0, 12]}
    96→            >
    97→              Key storage
    98→            </Text>
    99→            {isLoading ? (
   100→              <Block paddings={[20, 12]} align="center">
   101→                <Loading isFullScreen={false} />
   102→              </Block>
   103→            ) : (
   104→              <RadioButton
   105→                disabled={isTransitioning}
   106→                checked={isBackupEnabled}
   107→                onToggle={handleToggleKeyStorage}
   108→                label="Allow key storage"
   109→              />
   110→            )}
   111→            <Block flexDirection="row" gap={12}>
   112→              <Image source={require("assets/icons/info.png")} />
   113→              <Text size={TextSize.tiny} color={Colors.white50} flex={1}>
   114→                Store your cryptographic identity and message keys securely on
   115→                the server. This will allow you to view your message history on
   116→                any new devices.
   117→              </Text>
   118→            </Block>
   119→          </Block>
   120→        )}
   121→        {isBackupEnabled && (
   122→          <Block width="100%" gap={8}>
   123→            <Button.Wrapper
   124→              style={styles.button}
   125→              onPress={() => navigation.navigate("setUpRecoveryKey")}
   126→            >
   127→              <Block
   128→                paddings={[20, 12]}
   129→                flexDirection="row"
   130→                align="center"
   131→                justify="space-between"
   132→                border={{
   133→                  borderRadius: 16,
   134→                }}
   135→                background={Colors.white5}
   136→              >
   137→                <Text flex={1} size={TextSize.base}>
   138→                  {recoveryText()}
   139→                </Text>
   140→                <Image
   141→                  source={require("assets/icons/caret-left.png")}
   142→                  style={styles.caret}
   143→                />
   144→              </Block>
   145→            </Button.Wrapper>
   146→            <Block flexDirection="row" gap={12}>
   147→              <Image source={require("assets/icons/info.png")} />
   148→              <Text size={TextSize.tiny} color={Colors.white50} flex={1}>
   149→                Get access to your encrypted messages if you lose all your
   150→                devices or are signed out of Cloak everywhere.
   151→              </Text>
   152→            </Block>
   153→          </Block>
   154→        )}
   155→        <DisableKeyStorageModal
   156→          visible={isDisableKeyStorageModalVisible}
   157→          onClose={() => setIsDisableKeyStorageModalVisible(false)}
   158→        />
   159→      </Block>
   160→    </ScreenLayout>
   161→  );
   162→};
   163→
   164→const styles = StyleSheet.create({
   165→  button: {
   166→    width: "100%",
   167→  },
   168→  caret: {
   169→    transform: [{ rotate: "180deg" }],
   170→    width: 24,
   171→    height: 24,
   172→    marginLeft: "auto",
   173→  },
   174→});
