     1→import {
     2→  BackupState,
     3→  type EnableRecoveryProgressListener,
     4→  RecoveryState,
     5→  type TaskHandleInterface,
     6→} from "@unomed/react-native-matrix-sdk";
     7→import { mapBackupState } from "../../matrix-client/utils";
     8→import { MatrixCore } from "../../matrix-client/services/MatrixCore";
     9→
    10→export class EncryptionService {
    11→  public static setNewRecoveryKey = async () => {
    12→    return MatrixCore.getClient().encryption().resetRecoveryKey();
    13→  };
    14→
    15→  public static enableBackups = async () => {
    16→    await MatrixCore.getClient().encryption().enableBackups();
    17→  };
    18→
    19→  public static subscribeToBackupState = (
    20→    callback: (state: MappedBackupState) => void,
    21→  ): TaskHandleInterface => {
    22→    return MatrixCore.getClient().encryption().backupStateListener({
    23→      onUpdate: async (state: BackupState) => {
    24→        if (state === BackupState.Unknown) {
    25→          const backupExists = await MatrixCore.getClient()
    26→            .encryption()
    27→            .backupExistsOnServer();
    28→
    29→          callback(backupExists ? "enabled" : "unknown");
    30→          return;
    31→        }
    32→        callback(mapBackupState(state));
    33→      },
    34→    });
    35→  };
    36→
    37→  public static subscribeToRecoveryState = (
    38→    callback: (state: RecoveryState) => void,
    39→  ): TaskHandleInterface => {
    40→    return MatrixCore.getClient().encryption().recoveryStateListener({
    41→      onUpdate: (state: RecoveryState) => {
    42→        callback(state);
    43→      },
    44→    });
    45→  };
    46→
    47→  public static getBackupState = async (): Promise<MappedBackupState> => {
    48→    const client = MatrixCore.getClient();
    49→    await client.encryption().waitForE2eeInitializationTasks();
    50→    const backupExists = await client.encryption().backupExistsOnServer();
    51→    return backupExists ? "enabled" : "unknown";
    52→  };
    53→
    54→  public static getRecoveryState = async () => {
    55→    const client = MatrixCore.getClient();
    56→    await client.encryption().waitForE2eeInitializationTasks();
    57→    return client.encryption().recoveryState();
    58→  };
    59→
    60→  public static isRecoveryEnabled = async () => {
    61→    if (!MatrixCore.instance) return false;
    62→    const backupState = await EncryptionService.getBackupState();
    63→    const recoveryState = await EncryptionService.getRecoveryState();
    64→    const backupExists = backupState === "enabled";
    65→    const recoveryDisabled = recoveryState === RecoveryState.Disabled;
    66→    return backupExists && !recoveryDisabled;
    67→  };
    68→
    69→  public static enableRecovery = async (passphrase?: string) => {
    70→    const encryption = MatrixCore.getClient().encryption();
    71→
    72→    const progressListener: EnableRecoveryProgressListener = {
    73→      onUpdate: (status) => {
    74→        console.log("🔐 Recovery progress:", status);
    75→      },
    76→    };
    77→
    78→    const recoveryKey = await encryption.enableRecovery(
    79→      true,
    80→      passphrase,
    81→      progressListener,
    82→    );
    83→
    84→    await encryption.recover(recoveryKey);
    85→
    86→    console.log("✅ Recovery enabled! Save your recovery key securely.");
    87→    return recoveryKey;
    88→  };
    89→
    90→  public static resetRecoveryKey = async () => {
    91→    const encryption = MatrixCore.getClient().encryption();
    92→    const newRecoveryKey = await encryption.resetRecoveryKey();
    93→    await encryption.recover(newRecoveryKey);
    94→    console.log("✅ Recovery key reset! Save your new recovery key securely.");
    95→    return newRecoveryKey;
    96→  };
    97→
    98→  public static recoverWithKey = async (recoveryKey: string) => {
    99→    await MatrixCore.getClient().encryption().recover(recoveryKey);
   100→    console.log("✅ Successfully recovered using recovery key!");
   101→  };
   102→
   103→  public static disableRecovery = async () => {
   104→    await MatrixCore.getClient().encryption().disableRecovery();
   105→    console.log("⚠️ Recovery disabled");
   106→  };
   107→
   108→  public static resetIdentity = async () => {
   109→    await MatrixCore.getClient().encryption().resetIdentity();
   110→    console.log("✅ Identity reset successfully");
   111→  };
   112→}
   113→

